<section><h1>Role permissions</h1><form method="post" action="<?= dts_escape(site_url('role_permissions/assign')) ?>" class="inline-form"><select name="role_id" required><?php foreach ($roles as $role): ?><option value="<?= dts_escape($role['role_id']) ?>"><?= dts_escape($role['role_name']) ?></option><?php endforeach; ?></select><select name="permission_id" required><?php foreach ($permissions as $permission): ?><option value="<?= dts_escape($permission['permission_id']) ?>"><?= dts_escape($permission['module_label'].' · '.$permission['action_label']) ?></option><?php endforeach; ?></select><button type="submit">Assign</button></form><div class="table-wrap"><table><thead><tr><th>Role</th><th>Permission</th><th></th></tr></thead><tbody><?php foreach (($result['items'] ?? array()) as $row): ?><tr><td><?= dts_escape($row['role_name']) ?></td><td><?= dts_escape($row['permission_name']) ?></td><td><form method="post" action="<?= dts_escape(site_url('role_permissions/remove/'.$row['role_permission_id'])) ?>"><button type="submit" data-confirm="Remove this permission assignment?">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
